public class Dog {
    private String name;
    private int age;

    public Dog(String name, int age) {
        this.name = name; // assign name
        this.age = age;   // assign age
    }

    public void bark() {
        System.out.println(name + " says: Woof!"); // output
    }

    public int getAge() {
        return age; // return age
    }
}

public class Main {
    public static void main(String[] args) {
        Dog fido = new Dog("Fido", 3); // instantiate dog
        fido.bark();                  // call method
        System.out.println(fido.getAge() + " years old"); // print age
    }
}

